import { chromium } from 'playwright'

const browser = await chromium.launch({ headless: true })
const page = await browser.newPage()
const hits = []
page.on('response', async (res) => {
  const u = res.url()
  if (u.includes('/code') || u.includes('userLogin') || u.includes('/security/')) {
    let body = ''
    try { body = (await res.text()).slice(0, 400) } catch (e) { body = 'ERR ' + e.message }
    hits.push({ url: u, status: res.status(), body })
  }
})
await page.goto('http://localhost:8120/login', { waitUntil: 'networkidle', timeout: 30000 }).catch(e => console.log('goto err', e.message))
await page.waitForTimeout(2500)
console.log('FINAL_URL', page.url())
console.log('HITS', JSON.stringify(hits, null, 2))
await browser.close()

