import fs from 'fs'
import path from 'path'

const CHROME = 'C:/Users/Administrator/AppData/Local/ms-playwright/chromium-1243/chrome-win64/chrome.exe'
const TMP = process.env.TEMP || 'C:/Users/Administrator/AppData/Local/Temp'
const TOKEN = fs.readFileSync(path.join(TMP, 'zs2908-token.txt'), 'utf-8').trim()

const browser = await chromium.launch({ headless: true, executablePath: CHROME })
const ctx = await browser.newContext({ viewport: { width: 1600, height: 1000 } })
await ctx.addInitScript((t) => { sessionStorage.setItem('Admin-Token', t) }, TOKEN)
const page = await ctx.newPage()
const errs = []
page.on('console', m => { if (m.type() === 'error') errs.push(m.text().slice(0, 200)) })

await page.goto('http://localhost:8120/', { waitUntil: 'domcontentloaded', timeout: 30000 })
await page.waitForTimeout(4000)
