  try {
    const r = window.__VUE_APP_ROUTER__
    if (!r) return 'NO_ROUTER'
    return r.getRoutes().map(x => x.path).filter(p => /user|系统|system/i.test(p))
  } catch (e) { return 'ERR ' + e.message }
})
console.log('USER_ROUTES', JSON.stringify(routes))
console.log('ERRS', JSON.stringify(errs.slice(0, 5)))
